import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import styles from './Alert.module.css';

type AlertStatus = 'info' | 'success' | 'warning' | 'error';

type AlertProps = HTMLArkProps<'div'> & {
  status?: AlertStatus;
};

function Alert(props: AlertProps) {
  const [local, others] = splitProps(props, ['class', 'role', 'status']);

  return (
    <ark.div
      role={local.role}
      class={clsx(styles.root, local.class)}
      {...others}
      data-scope="alert"
      data-part="root"
      data-status={local.status ?? 'info'}
      data-slot="alert-root"
    />
  );
}

function AlertIndicator(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      aria-hidden="true"
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-scope="alert"
      data-part="indicator"
      data-slot="alert-indicator"
    />
  );
}

function AlertContent(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      class={clsx(styles.content, local.class)}
      {...others}
      data-scope="alert"
      data-part="content"
      data-slot="alert-content"
    />
  );
}

function AlertTitle(props: HTMLArkProps<'p'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.p
      class={clsx(styles.title, local.class)}
      {...others}
      data-scope="alert"
      data-part="title"
      data-slot="alert-title"
    />
  );
}

function AlertDescription(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      class={clsx(styles.description, local.class)}
      {...others}
      data-scope="alert"
      data-part="description"
      data-slot="alert-description"
    />
  );
}

function AlertActions(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      class={clsx(styles.actions, local.class)}
      {...others}
      data-scope="alert"
      data-part="actions"
      data-slot="alert-actions"
    />
  );
}

export { Alert, AlertActions, AlertContent, AlertDescription, AlertIndicator, AlertTitle };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    align-items: start;
    width: 100%;
    min-width: 0;
    gap: var(--moduix-alert-gap, var(--moduix-spacing-3));
    border: var(--moduix-alert-border-width, var(--moduix-border-width-sm)) solid
      var(
        --moduix-alert-border-color,
        var(--_alert-border-color-default, var(--moduix-color-border))
      );
    border-radius: var(--moduix-alert-radius, var(--moduix-radius-lg));
    padding: var(--moduix-alert-padding, var(--moduix-spacing-3));
    background-color: var(--moduix-alert-bg, var(--_alert-bg-default, var(--moduix-color-card)));
    color: var(
      --moduix-alert-color,
      var(--_alert-color-default, var(--moduix-color-card-foreground))
    );
    box-shadow: var(--moduix-alert-shadow, none);
    --_alert-bg-default: var(--moduix-alert-info-bg, var(--moduix-color-card));
    --_alert-border-color-default: var(
      --moduix-alert-info-border-color,
      var(--moduix-color-border)
    );
    --_alert-color-default: var(--moduix-alert-info-color, var(--moduix-color-card-foreground));
    --_alert-indicator-color-default: var(
      --moduix-alert-info-indicator-color,
      var(--moduix-color-muted-foreground)
    );

    &[data-status='success'] {
      --_alert-bg-default: var(
        --moduix-alert-success-bg,
        color-mix(in oklab, var(--moduix-color-success) 10%, var(--moduix-color-background))
      );
      --_alert-border-color-default: var(
        --moduix-alert-success-border-color,
        color-mix(in oklab, var(--moduix-color-success) 34%, transparent)
      );
      --_alert-color-default: var(--moduix-alert-success-color, var(--moduix-color-foreground));
      --_alert-indicator-color-default: var(
        --moduix-alert-success-indicator-color,
        var(--moduix-color-success)
      );
    }

    &[data-status='warning'] {
      --_alert-bg-default: var(
        --moduix-alert-warning-bg,
        color-mix(in oklab, var(--moduix-color-warning) 13%, var(--moduix-color-background))
      );
      --_alert-border-color-default: var(
        --moduix-alert-warning-border-color,
        color-mix(in oklab, var(--moduix-color-warning) 38%, transparent)
      );
      --_alert-color-default: var(--moduix-alert-warning-color, var(--moduix-color-foreground));
      --_alert-indicator-color-default: var(
        --moduix-alert-warning-indicator-color,
        var(--moduix-color-warning)
      );
    }

    &[data-status='error'] {
      --_alert-bg-default: var(
        --moduix-alert-error-bg,
        color-mix(in oklab, var(--moduix-color-destructive) 9%, var(--moduix-color-background))
      );
      --_alert-border-color-default: var(
        --moduix-alert-error-border-color,
        color-mix(in oklab, var(--moduix-color-destructive) 35%, transparent)
      );
      --_alert-color-default: var(--moduix-alert-error-color, var(--moduix-color-foreground));
      --_alert-indicator-color-default: var(
        --moduix-alert-error-indicator-color,
        var(--moduix-color-destructive)
      );
    }
  }

  .indicator {
    display: inline-flex;
    width: var(--moduix-alert-indicator-size, var(--moduix-spacing-4));
    height: var(--moduix-alert-indicator-size, var(--moduix-spacing-4));
    align-items: center;
    justify-content: center;
    color: var(--moduix-alert-indicator-color, var(--_alert-indicator-color-default, currentColor));
    margin-block-start: var(--moduix-alert-indicator-offset, var(--moduix-spacing-0-5));

    & :where(svg) {
      width: var(--moduix-alert-indicator-size, var(--moduix-spacing-4));
      height: var(--moduix-alert-indicator-size, var(--moduix-spacing-4));
      flex-shrink: 0;
      pointer-events: none;
    }
  }

  .content {
    display: grid;
    flex: 1;
    min-width: 0;
    gap: var(--moduix-alert-content-gap, var(--moduix-spacing-1));
  }

  .title {
    margin: 0;
    min-width: 0;
    color: var(--moduix-alert-title-color, var(--moduix-alert-color, var(--_alert-color-default)));
    font-size: var(--moduix-alert-title-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-alert-title-font-weight, var(--moduix-weight-semibold));
    line-height: var(--moduix-alert-title-line-height, var(--moduix-line-height-text-sm));
    overflow-wrap: anywhere;
  }

  .description {
    min-width: 0;
    color: var(--moduix-alert-description-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-alert-description-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-alert-description-line-height, var(--moduix-line-height-text-sm));
    overflow-wrap: anywhere;

    & > :first-child {
      margin-block-start: 0;
    }

    & > :last-child {
      margin-bottom: 0;
    }
  }

  .actions {
    display: flex;
    flex-wrap: wrap;
    margin-block-start: var(--moduix-alert-actions-margin-top, var(--moduix-spacing-2));
    gap: var(--moduix-alert-actions-gap, var(--moduix-spacing-2));
  }
}

export {
  Alert,
  AlertActions,
  AlertContent,
  AlertDescription,
  AlertIndicator,
  AlertTitle,
} from './Alert.js';
